SELECT c.relname,c.relrowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('vp_market_evidence','vp_case_market_evidence');
SELECT tablename,policyname,cmd,qual FROM pg_policies WHERE schemaname='public' AND tablename IN ('vp_market_evidence','vp_case_market_evidence');
SELECT p.proname,p.prosecdef,has_function_privilege('anon',p.oid,'EXECUTE') anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') authenticated_execute FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'vp_p17_%' ORDER BY p.proname;
SELECT t,has_table_privilege('authenticated',t,'SELECT') can_read,has_table_privilege('authenticated',t,'INSERT') can_insert,has_table_privilege('authenticated',t,'UPDATE') can_update,has_table_privilege('authenticated',t,'DELETE') can_delete FROM unnest(ARRAY['public.vp_market_evidence','public.vp_case_market_evidence']) t;
SELECT round(public.vp_p17_convert_measure(1,'acre','sqyd'),6)=4840 AS acre_test,round(public.vp_p17_convert_measure(1,'gunta','sqyd'),6)=121 AS gunta_test,round(public.vp_p17_convert_measure(1,'sqyd','sqft'),6)=9 AS square_yard_test,round(public.vp_p17_convert_measure(1,'cent','sqyd'),6)=48.4 AS cent_test,round(public.vp_p17_convert_measure(100,'per_sqft','per_sqyd'),6)=900 AS rate_test;
